import base64, csv, io, json, subprocess, sys, os

HEADER = 'type,id,revision,published,op,lease,event,probe,target,responder,result,service,attempt,payload'

def b64(data):
    return base64.b64encode(data).decode()

def rows_to_csv(rows):
    out = io.StringIO(newline='')
    w = csv.writer(out, lineterminator='\n')
    w.writerow(HEADER.split(','))
    for r in rows:
        w.writerow(r)
    return out.getvalue()

def make_capture(rows, encoding='csv'):
    text = rows if isinstance(rows, str) else rows_to_csv(rows)
    data = text.encode('utf-8')
    if encoding == 'zstd':
        sys.path.insert(0, '/workspace/deps')
        import zstandard as zstd
        data = zstd.ZstdCompressor().compress(data)
    return {'encoding': encoding, 'chunks': [b64(data)]}

BASE_QUOTA = [{'id': 'q', 'parent': None, 'capacity': 4096}]

def campaign(leases, services, queries, captures, requests=(), offers=(),
             rq=None, oq=None, seed='demo'):
    return {'version': 3, 'seed': seed, 'leases': list(leases),
            'services': [{'id': k, 'kind': v} for k, v in services.items()],
            'queries': list(queries), 'captures': list(captures),
            'requests': list(requests), 'offers': list(offers),
            'request_quotas': BASE_QUOTA if rq is None else list(rq),
            'offer_quotas': BASE_QUOTA if oq is None else list(oq)}

def lease(id, prefix, start=0, end=100, subnets=(0,), low=2):
    return {'id': id, 'prefix': prefix, 'start': start, 'end': end,
            'subnets': list(subnets), 'low_count': low}

def request(id, at, lease_id, target, service='web', group='q'):
    return {'id': id, 'at': at, 'lease': lease_id, 'target': target,
            'service': service, 'group': group}

def offer(id, time, service, prefix, capacity=1, cost=0, group='q', requests=()):
    return {'id': id, 'time': time, 'service': service, 'prefix': prefix,
            'capacity': capacity, 'cost': cost, 'group': group,
            'requests': list(requests)}

def icmp(id, revision, published, op, lease_id='', event='', probe='', target='',
         responder='', result='', rowtype='icmp'):
    return [rowtype, id, str(revision), str(published), op, lease_id,
            str(event) if event != '' else '', probe, target, responder, result,
            '', '', '']

def app(id, revision, published, op, lease_id='', event='', target='',
        result='', service='', attempt='', payload=''):
    return ['app', id, str(revision), str(published), op, lease_id,
            str(event) if event != '' else '', '', target, '', result, service,
            str(attempt) if attempt != '' else '', payload]

def run(job):
    proc = subprocess.run([sys.executable, '-I', '-B', '/workspace/submission/campaign.py'],
                          input=json.dumps(job).encode(), stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, cwd='/tmp')
    return json.loads(proc.stdout.decode()), proc.stderr.decode()

def check(name, got, want):
    if got == want:
        print('PASS', name)
        return True
    print('FAIL', name)
    print(' got:', json.dumps(got, indent=1, sort_keys=True)[:2500])
    print('want:', json.dumps(want, indent=1, sort_keys=True)[:2500])
    return False
